"use client";

import { useState } from "react";

export default function Counter() {
  const [count, setCount] = useState(0);

  return (
    <div className="flex flex-col items-center gap-4">
      <h1 className="text-3xl font-bold">Contador</h1>

      <div className="flex items-center gap-6">
        <button
          type="button"
          onClick={() => setCount((c) => c - 1)}
          className="h-12 w-12 rounded-lg bg-gray-200 text-2xl text-gray-900 transition hover:bg-gray-300"
          aria-label="Restar"
        >
          -
        </button>

        <span className="min-w-[3ch] text-center text-4xl font-bold">
          {count}
        </span>

        <button
          type="button"
          onClick={() => setCount((c) => c + 1)}
          className="h-12 w-12 rounded-lg bg-gray-200 text-2xl text-gray-900 transition hover:bg-gray-300"
          aria-label="Sumar"
        >
          +
        </button>
      </div>

      <p className="text-lg">El doble es {count * 2}</p>

      {count > 5 && (
        <p className="text-lg font-semibold text-green-600">¡Más de 5!</p>
      )}
    </div>
  );
}

