"use client";

import { useState } from "react";

type Product = {
  id: number;
  nombre: string;
  precio: number;
};

const PRODUCTS: Product[] = [
  { id: 1, nombre: "Auriculares inalámbricos", precio: 49.99 },
  { id: 2, nombre: "Teclado mecánico", precio: 89.5 },
  { id: 3, nombre: "Mouse ergonómico", precio: 29.9 },
];

export default function Cart() {
  const [quantities, setQuantities] = useState<Record<number, number>>({});

  const add = (id: number) => {
    setQuantities((prev) => ({ ...prev, [id]: (prev[id] ?? 0) + 1 }));
  };

  const remove = (id: number) => {
    setQuantities((prev) => {
      const current = prev[id] ?? 0;
      const next = { ...prev };
      if (current <= 1) {
        delete next[id];
      } else {
        next[id] = current - 1;
      }
      return next;
    });
  };

  const cartItems = PRODUCTS.filter((p) => (quantities[p.id] ?? 0) > 0).map(
    (p) => ({ ...p, cantidad: quantities[p.id] })
  );

  const total = cartItems.reduce((acc, i) => acc + i.precio * i.cantidad, 0);

  return (
    <div className="grid gap-8 sm:grid-cols-2">
      <section>
        <h2 className="mb-4 text-xl font-semibold text-gray-800">Productos</h2>
        <ul className="space-y-3">
          {PRODUCTS.map((p) => (
            <li
              key={p.id}
              className="flex items-center justify-between rounded-lg bg-white p-4 shadow-sm"
            >
              <div>
                <p className="font-medium text-gray-900">{p.nombre}</p>
                <p className="text-sm text-gray-500">${p.precio.toFixed(2)}</p>
              </div>
              <button
                onClick={() => add(p.id)}
                className="rounded-md bg-blue-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-blue-700"
              >
                Agregar
              </button>
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h2 className="mb-4 text-xl font-semibold text-gray-800">Carrito</h2>
        {cartItems.length === 0 ? (
          <p className="rounded-lg bg-white p-4 text-gray-500 shadow-sm">
            El carrito está vacío.
          </p>
        ) : (
          <ul className="space-y-3">
            {cartItems.map((item) => (
              <li
                key={item.id}
                className="flex items-center justify-between rounded-lg bg-white p-4 shadow-sm"
              >
                <div>
                  <p className="font-medium text-gray-900">{item.nombre}</p>
                  <p className="text-sm text-gray-500">
                    ${item.precio.toFixed(2)} c/u
                  </p>
                </div>
                <div className="flex items-center gap-3">
                  <button
                    onClick={() => remove(item.id)}
                    aria-label={`Quitar una unidad de ${item.nombre}`}
                    className="h-8 w-8 rounded-md bg-gray-200 font-bold text-gray-800 hover:bg-gray-300"
                  >
                    -
                  </button>
                  <span className="w-6 text-center font-medium text-gray-900">
                    {item.cantidad}
                  </span>
                  <button
                    onClick={() => add(item.id)}
                    aria-label={`Agregar una unidad de ${item.nombre}`}
                    className="h-8 w-8 rounded-md bg-gray-200 font-bold text-gray-800 hover:bg-gray-300"
                  >
                    +
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
        <div className="mt-4 flex items-center justify-between rounded-lg bg-white p-4 shadow-sm">
          <span className="font-semibold text-gray-800">Total</span>
          <span className="text-lg font-bold text-gray-900">
            ${total.toFixed(2)}
          </span>
        </div>
      </section>
    </div>
  );
}

