import { useState } from "react";

type Product = {
  id: number;
  nombre: string;
  precio: number;
};

type CartItem = {
  producto: Product;
  cantidad: number;
};

const PRODUCTS: Product[] = [
  { id: 1, nombre: "Remera", precio: 12500.5 },
  { id: 2, nombre: "Zapatillas", precio: 48999.99 },
  { id: 3, nombre: "Gorra", precio: 7800 },
];

export default function Cart() {
  const [items, setItems] = useState<CartItem[]>([]);

  const agregar = (producto: Product) => {
    setItems((prev) => {
      const existe = prev.find((i) => i.producto.id === producto.id);
      if (existe) {
        return prev.map((i) =>
          i.producto.id === producto.id ? { ...i, cantidad: i.cantidad + 1 } : i
        );
      }
      return [...prev, { producto, cantidad: 1 }];
    });
  };

  const cambiarCantidad = (id: number, delta: number) => {
    setItems((prev) =>
      prev
        .map((i) =>
          i.producto.id === id ? { ...i, cantidad: i.cantidad + delta } : i
        )
        .filter((i) => i.cantidad > 0)
    );
  };

  const total = items.reduce(
    (acc, i) => acc + i.producto.precio * i.cantidad,
    0
  );

  return (
    <div className="grid gap-8 md:grid-cols-2">
      <section>
        <h2 className="mb-4 text-xl font-semibold text-gray-800">Productos</h2>
        <ul className="space-y-3">
          {PRODUCTS.map((p) => (
            <li
              key={p.id}
              className="flex items-center justify-between rounded-lg border border-gray-200 bg-white p-4 shadow-sm"
            >
              <div>
                <p className="font-medium text-gray-900">{p.nombre}</p>
                <p className="text-sm text-gray-500">${p.precio.toFixed(2)}</p>
              </div>
              <button
                onClick={() => agregar(p)}
                className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
              >
                Agregar
              </button>
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h2 className="mb-4 text-xl font-semibold text-gray-800">Carrito</h2>
        <div className="rounded-lg border border-gray-200 bg-white p-4 shadow-sm">
          {items.length === 0 ? (
            <p className="text-gray-500">El carrito está vacío.</p>
          ) : (
            <ul className="divide-y divide-gray-100">
              {items.map(({ producto, cantidad }) => (
                <li
                  key={producto.id}
                  className="flex items-center justify-between py-3"
                >
                  <div>
                    <p className="font-medium text-gray-900">
                      {producto.nombre}
                    </p>
                    <p className="text-sm text-gray-500">
                      ${producto.precio.toFixed(2)} c/u
                    </p>
                  </div>
                  <div className="flex items-center gap-3">
                    <button
                      onClick={() => cambiarCantidad(producto.id, -1)}
                      aria-label={`Quitar una unidad de ${producto.nombre}`}
                      className="h-8 w-8 rounded-md bg-gray-200 font-bold text-gray-800 hover:bg-gray-300"
                    >
                      -
                    </button>
                    <span className="w-6 text-center text-gray-900">
                      {cantidad}
                    </span>
                    <button
                      onClick={() => cambiarCantidad(producto.id, 1)}
                      aria-label={`Agregar una unidad de ${producto.nombre}`}
                      className="h-8 w-8 rounded-md bg-gray-200 font-bold text-gray-800 hover:bg-gray-300"
                    >
                      +
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
          <div className="mt-4 flex items-center justify-between border-t border-gray-200 pt-4">
            <span className="text-lg font-semibold text-gray-800">Total</span>
            <span className="text-lg font-bold text-gray-900">
              ${total.toFixed(2)}
            </span>
          </div>
        </div>
      </section>
    </div>
  );
}

