"use client";

import { useState } from "react";

const tabs = [
  {
    id: "perfil",
    label: "Perfil",
    content:
      "Acá podés ver y editar tu información personal: nombre, foto, correo electrónico y biografía.",
  },
  {
    id: "ajustes",
    label: "Ajustes",
    content:
      "Configurá las preferencias de tu cuenta: notificaciones, privacidad, idioma y tema de la aplicación.",
  },
  {
    id: "ayuda",
    label: "Ayuda",
    content:
      "¿Necesitás una mano? Consultá las preguntas frecuentes o escribinos a nuestro equipo de soporte.",
  },
];

export default function Tabs() {
  const [active, setActive] = useState(tabs[0].id);
  const current = tabs.find((t) => t.id === active) ?? tabs[0];

  return (
    <div>
      <div
        role="tablist"
        className="flex gap-2 border-b border-gray-200"
      >
        {tabs.map((tab) => {
          const isActive = tab.id === active;
          return (
            <button
              key={tab.id}
              type="button"
              role="tab"
              id={`tab-${tab.id}`}
              aria-selected={isActive}
              aria-controls={`panel-${tab.id}`}
              onClick={() => setActive(tab.id)}
              className={`px-4 py-2 text-sm font-medium rounded-t-md border-b-2 -mb-px transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 ${
                isActive
                  ? "border-blue-600 text-blue-700 bg-blue-50"
                  : "border-transparent text-gray-600 hover:text-gray-900 hover:bg-gray-100"
              }`}
            >
              {tab.label}
            </button>
          );
        })}
      </div>

      <div
        role="tabpanel"
        id={`panel-${current.id}`}
        aria-labelledby={`tab-${current.id}`}
        className="mt-4 p-4 bg-white rounded-md border border-gray-200 text-gray-700"
      >
        {current.content}
      </div>
    </div>
  );
}

