"use client";

import { useEffect, useState } from "react";

type User = {
  id: string;
  name: string;
  email: string;
};

export default function UserManager() {
  const [users, setUsers] = useState<User[]>([]);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  async function loadUsers() {
    try {
      const res = await fetch("/api/users", { cache: "no-store" });
      if (res.ok) {
        setUsers(await res.json());
      }
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadUsers();
  }, []);

  async function handleAdd() {
    if (!email.includes("@")) {
      setError("Email inválido");
      return;
    }
    setError("");

    const res = await fetch("/api/users", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, email }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      setError(data.error ?? "Error al crear el usuario");
      return;
    }

    setName("");
    setEmail("");
    await loadUsers();
  }

  async function handleDelete(id: string) {
    const res = await fetch(`/api/users/${id}`, { method: "DELETE" });
    if (res.ok || res.status === 404) {
      await loadUsers();
    }
  }

  return (
    <div className="mx-auto w-full max-w-xl p-6">
      <h1 className="mb-6 text-2xl font-bold">Usuarios</h1>

      <div className="mb-2 flex flex-col gap-2 sm:flex-row">
        <input
          type="text"
          placeholder="Nombre"
          value={name}
          onChange={(e) => setName(e.target.value)}
          className="flex-1 rounded border border-gray-300 px-3 py-2 text-black"
        />
        <input
          type="text"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="flex-1 rounded border border-gray-300 px-3 py-2 text-black"
        />
        <button
          onClick={handleAdd}
          className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
        >
          Agregar
        </button>
      </div>

      {error && <p className="mb-4 text-sm text-red-600">{error}</p>}

      <ul className="mt-4 flex flex-col gap-2">
        {users.map((user) => (
          <li
            key={user.id}
            className="flex items-center justify-between rounded border border-gray-300 px-3 py-2"
          >
            <div className="flex flex-col">
              <span className="font-medium">{user.name}</span>
              <span className="text-sm text-gray-500">{user.email}</span>
            </div>
            <button
              onClick={() => handleDelete(user.id)}
              className="rounded bg-red-600 px-3 py-1 text-white hover:bg-red-700"
            >
              Borrar
            </button>
          </li>
        ))}
      </ul>

      {!loading && users.length === 0 && (
        <p className="mt-4 text-sm text-gray-500">No hay usuarios.</p>
      )}
    </div>
  );
}

