"use client";

import { useCallback, useEffect, useState } from "react";

type Author = { id: string; name: string };
type Post = { id: string; title: string; authorId: string; authorName: string };

export default function Blog() {
  const [authors, setAuthors] = useState<Author[]>([]);
  const [posts, setPosts] = useState<Post[]>([]);
  const [authorName, setAuthorName] = useState("");
  const [title, setTitle] = useState("");
  const [authorId, setAuthorId] = useState("");
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    const [a, p] = await Promise.all([
      fetch("/api/authors", { cache: "no-store" }).then((r) => r.json()),
      fetch("/api/posts", { cache: "no-store" }).then((r) => r.json()),
    ]);
    setAuthors(a);
    setPosts(p);
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!authors.some((a) => a.id === authorId)) {
      setAuthorId(authors[0]?.id ?? "");
    }
  }, [authors, authorId]);

  async function createAuthor() {
    if (!authorName.trim()) return;
    setError("");
    await fetch("/api/authors", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: authorName }),
    });
    setAuthorName("");
    await load();
  }

  async function deleteAuthor(id: string) {
    setError("");
    const res = await fetch(`/api/authors/${id}`, { method: "DELETE" });
    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      setError(data.error ?? "Error");
    }
    await load();
  }

  async function createPost() {
    if (!title.trim() || !authorId) return;
    setError("");
    await fetch("/api/posts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, authorId }),
    });
    setTitle("");
    await load();
  }

  return (
    <div className="mx-auto max-w-2xl space-y-8 p-6">
      <h1 className="text-3xl font-bold">Blog</h1>

      {error && <p className="rounded bg-red-100 p-2 text-red-700">{error}</p>}

      <section className="space-y-3">
        <h2 className="text-xl font-semibold">Autores</h2>
        <div className="flex gap-2">
          <input
            className="flex-1 rounded border p-2"
            placeholder="Autor"
            value={authorName}
            onChange={(e) => setAuthorName(e.target.value)}
          />
          <button
            className="rounded bg-blue-600 px-4 py-2 text-white"
            onClick={createAuthor}
          >
            Crear autor
          </button>
        </div>
        <ul className="space-y-2">
          {authors.map((a) => (
            <li
              key={a.id}
              className="flex items-center justify-between rounded border p-2"
            >
              <span>{a.name}</span>
              <button
                className="rounded bg-red-600 px-3 py-1 text-white"
                onClick={() => deleteAuthor(a.id)}
              >
                Borrar autor
              </button>
            </li>
          ))}
        </ul>
      </section>

      <section className="space-y-3">
        <h2 className="text-xl font-semibold">Posts</h2>
        <div className="flex gap-2">
          <input
            className="flex-1 rounded border p-2"
            placeholder="Título"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <select
            className="rounded border p-2"
            value={authorId}
            onChange={(e) => setAuthorId(e.target.value)}
          >
            {authors.map((a) => (
              <option key={a.id} value={a.id}>
                {a.name}
              </option>
            ))}
          </select>
          <button
            className="rounded bg-green-600 px-4 py-2 text-white"
            onClick={createPost}
          >
            Publicar
          </button>
        </div>
        <ul className="space-y-2">
          {posts.map((p) => (
            <li key={p.id} className="rounded border p-3">
              <h3 className="font-semibold">{p.title}</h3>
              <p className="text-sm text-gray-600">por {p.authorName}</p>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}

