import { db, type Product } from "@/lib/db";

export const dynamic = "force-dynamic";

export async function GET() {
  return Response.json(db.products);
}

export async function POST(request: Request) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return Response.json({ error: "Solicitud inválida" }, { status: 400 });
  }

  const data = (body ?? {}) as Record<string, unknown>;
  const name = typeof data.name === "string" ? data.name.trim() : "";
  const code = typeof data.code === "string" ? data.code.trim() : "";
  const rawPrice = data.price;
  const price =
    typeof rawPrice === "number"
      ? rawPrice
      : typeof rawPrice === "string" && rawPrice.trim() !== ""
        ? Number(rawPrice)
        : NaN;

  if (name.length < 3) {
    return Response.json({ error: "Nombre muy corto" }, { status: 400 });
  }

  if (!Number.isFinite(price) || price < 0) {
    return Response.json({ error: "Precio inválido" }, { status: 400 });
  }

  if (db.products.some((p) => p.code === code)) {
    return Response.json({ error: "Código repetido" }, { status: 409 });
  }

  const product: Product = {
    id: crypto.randomUUID(),
    name,
    code,
    price,
  };
  db.products.push(product);

  return Response.json(product, { status: 201 });
}

