import { db } from "@/lib/db";

export const dynamic = "force-dynamic";

const MAX_SIZE = 5 * 1024 * 1024;

export async function GET() {
  if (!db.photo) {
    return new Response("No photo", { status: 404 });
  }
  return new Response(new Uint8Array(db.photo.data), {
    status: 200,
    headers: {
      "Content-Type": db.photo.type,
      "Cache-Control": "no-store",
    },
  });
}

export async function POST(request: Request) {
  let formData: FormData;
  try {
    formData = await request.formData();
  } catch {
    return Response.json({ error: "Formulario inválido" }, { status: 400 });
  }

  const file = formData.get("photo");
  if (!(file instanceof File) || file.size === 0) {
    return Response.json({ error: "No se envió ningún archivo" }, { status: 400 });
  }
  if (!file.type.startsWith("image/")) {
    return Response.json({ error: "El archivo debe ser una imagen" }, { status: 400 });
  }
  if (file.size > MAX_SIZE) {
    return Response.json({ error: "La imagen supera los 5 MB" }, { status: 413 });
  }

  const buffer = Buffer.from(await file.arrayBuffer());
  db.photo = { data: buffer, type: file.type, updatedAt: Date.now() };

  return Response.json({ ok: true, updatedAt: db.photo.updatedAt });
}

