"use client";

import { useEffect, useState } from "react";

export default function ProfilePhoto() {
  const [file, setFile] = useState<File | null>(null);
  const [version, setVersion] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch("/api/photo/info")
      .then((r) => r.json())
      .then((info: { hasPhoto: boolean; updatedAt: number | null }) => {
        if (!cancelled && info.hasPhoto) setVersion(info.updatedAt);
      })
      .catch(() => {
        if (!cancelled) setError("No se pudo cargar la foto");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  async function handleUpload() {
    if (!file) return;
    setUploading(true);
    setError(null);
    try {
      const fd = new FormData();
      fd.append("photo", file);
      const res = await fetch("/api/photo", { method: "POST", body: fd });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error ?? "Error al subir la foto");
      } else {
        setVersion(data.updatedAt);
        setFile(null);
        const input = document.getElementById("photo-input") as HTMLInputElement | null;
        if (input) input.value = "";
      }
    } catch {
      setError("Error de red al subir la foto");
    } finally {
      setUploading(false);
    }
  }

  return (
    <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-md">
      <h1 className="mb-6 text-2xl font-bold text-gray-900">Mi perfil</h1>

      <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
        <input
          id="photo-input"
          type="file"
          accept="image/*"
          onChange={(e) => setFile(e.target.files?.[0] ?? null)}
          className="block w-full text-sm text-gray-700 file:mr-3 file:rounded-lg file:border-0 file:bg-gray-100 file:px-4 file:py-2 file:text-sm file:font-medium hover:file:bg-gray-200"
        />
        <button
          type="button"
          onClick={handleUpload}
          disabled={!file || uploading}
          className="rounded-lg bg-blue-600 px-5 py-2 text-sm font-semibold text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
        >
          {uploading ? "Subiendo..." : "Subir"}
        </button>
      </div>

      {error && <p className="mt-3 text-sm text-red-600">{error}</p>}

      <div className="mt-6 flex min-h-48 items-center justify-center rounded-xl bg-gray-50 p-2">
        {loading ? (
          <p className="text-sm text-gray-500">Cargando...</p>
        ) : version !== null ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={`/api/photo?v=${version}`}
            alt="Foto de perfil"
            className="max-h-96 w-full rounded-lg object-contain"
          />
        ) : (
          <p className="text-sm text-gray-500">Todavía no subiste ninguna foto</p>
        )}
      </div>
    </div>
  );
}

