export default function ProfilePhoto() {
  const [file, setFile] = useState<File | null>(null);
  const [version, setVersion] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch("/api/photo/info")
      .then((r) => r.json())
      .then((info) => {
        if (!cancelled && info.hasPhoto) setVersion(info.updatedAt);
      })
      .catch(() => {})
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  async function handleUpload() {
    if (!file) return;
    setUploading(true);
    setError(null);
    try {
      const form = new FormData();
      form.append("photo", file);
      const res = await fetch("/api/photo", { method: "POST", body: form });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error ?? "Error al subir la foto");
      } else {
        setVersion(data.updatedAt);
        setFile(null);
        const input = document.getElementById("photo-input") as HTMLInputElement | null;
        if (input) input.value = "";
      }
    } catch {
      setError("Error de red al subir la foto");
    } finally {
      setUploading(false);
    }
  }

  return (
    <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-md">
      <h1 className="mb-6 text-2xl font-bold text-gray-900">Mi perfil</h1>

      <div className="flex flex-col gap-3">
        <input
          id="photo-input"
          type="file"
          accept="image/*"
          onChange={(e) => setFile(e.target.files?.[0] ?? null)}
          className="block w-full text-sm text-gray-700 file:mr-4 file:rounded-lg file:border-0 file:bg-gray-100 file:px-4 file:py-2 file:font-medium hover:file:bg-gray-200"
        />
        <button
          onClick={handleUpload}
          disabled={!file || uploading}
          className="rounded-lg bg-blue-600 px-4 py-2 font-medium text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
        >
          {uploading ? "Subiendo..." : "Subir"}
        </button>
        {error && <p className="text-sm text-red-600">{error}</p>}
      </div>

      <div className="mt-6 flex justify-center">
        {loading ? (
          <p className="text-sm text-gray-500">Cargando...</p>
        ) : version !== null ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={`/api/photo?v=${version}`}
            alt="Foto de perfil"
            className="h-64 w-64 rounded-full object-cover shadow"
          />
        ) : (
          <p className="text-sm text-gray-500">Todavía no subiste ninguna foto.</p>
        )}
      </div>
    </div>
  );
}

