"use client";

import { useState } from "react";

const TOTAL_ITEMS = 23;
const POR_PAGINA = 10;
const TOTAL_PAGINAS = Math.ceil(TOTAL_ITEMS / POR_PAGINA);

const items = Array.from({ length: TOTAL_ITEMS }, (_, i) => `Ítem ${i + 1}`);

export default function Paginacion() {
  const [pagina, setPagina] = useState(1);

  const inicio = (pagina - 1) * POR_PAGINA;
  const visibles = items.slice(inicio, inicio + POR_PAGINA);

  return (
    <div>
      <ul className="mb-6 divide-y divide-gray-200 rounded border border-gray-200">
        {visibles.map((item) => (
          <li key={item} className="px-4 py-2">
            {item}
          </li>
        ))}
      </ul>

      <div className="flex items-center justify-between">
        <button
          type="button"
          onClick={() => setPagina((p) => p - 1)}
          disabled={pagina === 1}
          className="rounded bg-blue-600 px-4 py-2 text-white disabled:cursor-not-allowed disabled:opacity-50"
        >
          Anterior
        </button>

        <span>
          Página {pagina} de {TOTAL_PAGINAS}
        </span>

        <button
          type="button"
          onClick={() => setPagina((p) => p + 1)}
          disabled={pagina === TOTAL_PAGINAS}
          className="rounded bg-blue-600 px-4 py-2 text-white disabled:cursor-not-allowed disabled:opacity-50"
        >
          Siguiente
        </button>
      </div>
    </div>
  );
}

