"use client";

import { useState } from "react";

type Employee = {
  nombre: string;
  edad: number;
};

const initialEmployees: Employee[] = [
  { nombre: "Caro", edad: 35 },
  { nombre: "Ana", edad: 30 },
  { nombre: "Dani", edad: 28 },
  { nombre: "Beto", edad: 25 },
];

export default function EmployeeTable() {
  const [employees, setEmployees] = useState<Employee[]>(initialEmployees);
  const [filter, setFilter] = useState("");

  const sortByName = () => {
    setEmployees((prev) =>
      [...prev].sort((a, b) => a.nombre.localeCompare(b.nombre, "es"))
    );
  };

  const sortByAge = () => {
    setEmployees((prev) => [...prev].sort((a, b) => a.edad - b.edad));
  };

  const visible = employees.filter((e) =>
    e.nombre.toLowerCase().includes(filter.trim().toLowerCase())
  );

  return (
    <div className="w-full max-w-md space-y-4">
      <div className="flex flex-wrap items-center gap-2">
        <button
          type="button"
          onClick={sortByName}
          className="rounded bg-blue-600 px-3 py-2 text-sm font-medium text-white hover:bg-blue-700"
        >
          Ordenar por nombre
        </button>
        <button
          type="button"
          onClick={sortByAge}
          className="rounded bg-blue-600 px-3 py-2 text-sm font-medium text-white hover:bg-blue-700"
        >
          Ordenar por edad
        </button>
      </div>

      <input
        type="text"
        placeholder="Filtrar"
        value={filter}
        onChange={(e) => setFilter(e.target.value)}
        className="w-full rounded border border-gray-300 px-3 py-2 text-sm text-black"
      />

      <table className="w-full border-collapse border border-gray-300 text-left">
        <thead>
          <tr className="bg-gray-100 text-black">
            <th className="border border-gray-300 px-3 py-2">Nombre</th>
            <th className="border border-gray-300 px-3 py-2">Edad</th>
          </tr>
        </thead>
        <tbody>
          {visible.map((e) => (
            <tr key={e.nombre}>
              <td className="border border-gray-300 px-3 py-2">{e.nombre}</td>
              <td className="border border-gray-300 px-3 py-2">{e.edad}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <p className="text-sm font-medium">Empleados: {visible.length}</p>
    </div>
  );
}

