"use client";

import { useEffect, useRef, useState } from "react";

export default function Cronometro() {
  const [tiempo, setTiempo] = useState(0);
  const [corriendo, setCorriendo] = useState(false);
  const intervaloRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (!corriendo) return;

    intervaloRef.current = setInterval(() => {
      setTiempo((t) => t + 1);
    }, 100);

    return () => {
      if (intervaloRef.current !== null) {
        clearInterval(intervaloRef.current);
        intervaloRef.current = null;
      }
    };
  }, [corriendo]);

  const iniciar = () => setCorriendo(true);
  const pausar = () => setCorriendo(false);
  const reiniciar = () => {
    setCorriendo(false);
    setTiempo(0);
  };

  return (
    <div className="flex flex-col items-center gap-6 rounded-2xl bg-white p-8 shadow-md">
      <p className="text-4xl font-bold tabular-nums text-zinc-900">
        Tiempo: {tiempo}
      </p>
      <div className="flex gap-3">
        <button
          onClick={iniciar}
          className="rounded-lg bg-green-600 px-4 py-2 font-medium text-white transition hover:bg-green-700"
        >
          Iniciar
        </button>
        <button
          onClick={pausar}
          className="rounded-lg bg-yellow-500 px-4 py-2 font-medium text-white transition hover:bg-yellow-600"
        >
          Pausar
        </button>
        <button
          onClick={reiniciar}
          className="rounded-lg bg-red-600 px-4 py-2 font-medium text-white transition hover:bg-red-700"
