import { useState } from "react";

type Plan = "Gratis" | "Pro";

export default function RegistroForm() {
  const [paso, setPaso] = useState(1);
  const [nombre, setNombre] = useState("");
  const [plan, setPlan] = useState<Plan>("Gratis");
  const [novedades, setNovedades] = useState(false);
  const [error, setError] = useState("");
  const [confirmado, setConfirmado] = useState(false);

  const siguienteDesdePaso1 = () => {
    if (nombre.trim() === "") {
      setError("Nombre requerido");
      return;
    }
    setError("");
    setPaso(2);
  };

  const btnPrimario =
    "rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700";
  const btnSecundario =
    "rounded border border-gray-300 px-4 py-2 text-gray-700 hover:bg-gray-100";

  if (confirmado) {
    return (
      <div className="w-full max-w-sm rounded-lg bg-white p-6 shadow">
        <p className="text-xl font-semibold text-green-700">
          ¡Listo, {nombre.trim()}!
        </p>
      </div>
    );
  }

  return (
    <div className="w-full max-w-sm rounded-lg bg-white p-6 shadow space-y-4">
      <h1 className="text-sm font-medium text-gray-500">Paso {paso} de 3</h1>

      {paso === 1 && (
        <div className="space-y-3">
          <input
            type="text"
            placeholder="Nombre"
            value={nombre}
            onChange={(e) => setNombre(e.target.value)}
            className="w-full rounded border border-gray-300 px-3 py-2"
          />
          {error && <p className="text-sm text-red-600">{error}</p>}
          <div className="flex gap-2">
            <button type="button" onClick={siguienteDesdePaso1} className={btnPrimario}>
              Siguiente
            </button>
          </div>
        </div>
      )}

      {paso === 2 && (
        <div className="space-y-3">
          <select
            value={plan}
            onChange={(e) => setPlan(e.target.value as Plan)}
            className="w-full rounded border border-gray-300 px-3 py-2"
          >
            <option value="Gratis">Gratis</option>
            <option value="Pro">Pro</option>
          </select>
          <label className="flex items-center gap-2">
            <input
              type="checkbox"
              checked={novedades}
              onChange={(e) => setNovedades(e.target.checked)}
            />
            Recibir novedades
          </label>
          <div className="flex gap-2">
            <button type="button" onClick={() => setPaso(1)} className={btnSecundario}>
              Atrás
            </button>
            <button type="button" onClick={() => setPaso(3)} className={btnPrimario}>
              Siguiente
            </button>
          </div>
        </div>
      )}

      {paso === 3 && (
        <div className="space-y-3">
          <p>
            {nombre.trim()} eligió {plan}
          </p>
          {novedades && <p>Con novedades</p>}
          <div className="flex gap-2">
            <button type="button" onClick={() => setPaso(2)} className={btnSecundario}>
              Atrás
            </button>
            <button type="button" onClick={() => setConfirmado(true)} className={btnPrimario}>
              Confirmar
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

