"use client";

import { useState } from "react";
import Note from "@/components/Note";

const initialNotes = [
  { id: 1, text: "Comprar pan" },
  { id: 2, text: "Llamar a Ana" },
  { id: 3, text: "Pagar luz" },
];

export default function NotesList() {
  const [notes, setNotes] = useState(initialNotes);
  const [editCount, setEditCount] = useState(0);

  function handleSave(id: number, newText: string) {
    const current = notes.find((n) => n.id === id);
    if (!current || current.text === newText) return;
    setNotes((prev) =>
      prev.map((n) => (n.id === id ? { ...n, text: newText } : n))
    );
    setEditCount((c) => c + 1);
  }

  return (
    <div>
      <ul className="space-y-2">
        {notes.map((note) => (
          <Note key={note.id} text={note.text} onSave={(t) => handleSave(note.id, t)} />
        ))}
      </ul>
      <p className="mt-4 font-medium">Editadas: {editCount}</p>
    </div>
  );
}

