"use client";

import { useState } from "react";

type NoteProps = {
  text: string;
  onSave: (newText: string) => void;
};

export default function Note({ text, onSave }: NoteProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(text);

  function startEdit() {
    setDraft(text);
    setEditing(true);
  }

  function save() {
    onSave(draft);
    setEditing(false);
  }

  function cancel() {
    setDraft(text);
    setEditing(false);
  }

  return (
    <li className="flex items-center justify-between gap-2 rounded border border-gray-300 p-3">
      {editing ? (
        <>
          <input
            className="flex-1 rounded border border-gray-400 px-2 py-1"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
          />
          <div className="flex gap-2">
            <button
              className="rounded bg-green-600 px-3 py-1 text-white"
              onClick={save}
            >
              Guardar
            </button>
            <button
              className="rounded bg-gray-500 px-3 py-1 text-white"
              onClick={cancel}
            >
              Cancelar
            </button>
          </div>
        </>
      ) : (
        <>
          <span>{text}</span>
          <button
            className="rounded bg-blue-600 px-3 py-1 text-white"
            onClick={startEdit}
          >
            Editar
          </button>
        </>
      )}
    </li>
  );
}

