import { useState } from "react";

type NoteProps = {
  text: string;
  onSave: (newText: string) => void;
};

export default function Note({ text, onSave }: NoteProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(text);

  function startEditing() {
    setDraft(text);
    setEditing(true);
  }

  function save() {
    onSave(draft);
    setEditing(false);
  }

  function cancel() {
    setDraft(text);
    setEditing(false);
  }

  return (
    <li className="flex items-center justify-between gap-2 rounded border border-gray-300 p-3">
      {editing ? (
        <>
          <input
            type="text"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            className="flex-1 rounded border border-gray-300 px-2 py-1"
