"use client";

import { useEffect, useState } from "react";

type Task = {
  id: string;
  title: string;
  done: boolean;
};

type Filter = "todas" | "pendientes" | "hechas";

export default function TaskManager() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [text, setText] = useState("");
  const [filter, setFilter] = useState<Filter>("todas");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editText, setEditText] = useState("");

  useEffect(() => {
    let cancelled = false;
    fetch("/api/tasks", { cache: "no-store" })
      .then((r) => r.json())
      .then((data: Task[]) => {
        if (!cancelled) setTasks(data);
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, []);

  async function addTask() {
    const title = text.trim();
    if (!title) return;
    const res = await fetch("/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title }),
    });
    if (res.ok) {
      const task: Task = await res.json();
      setTasks((prev) => [...prev, task]);
      setText("");
    }
  }

  async function markDone(id: string) {
    const res = await fetch(`/api/tasks/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ done: true }),
    });
    if (res.ok) {
      const updated: Task = await res.json();
      setTasks((prev) => prev.map((t) => (t.id === id ? updated : t)));
    }
  }

  function startEdit(task: Task) {
    setEditingId(task.id);
    setEditText(task.title);
  }

  async function saveTitle(id: string) {
    const title = editText.trim();
    if (!title) return;
    const res = await fetch(`/api/tasks/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title }),
    });
    if (res.ok) {
      const updated: Task = await res.json();
      setTasks((prev) => prev.map((t) => (t.id === id ? updated : t)));
      setEditingId(null);
      setEditText("");
    }
  }

  const visible = tasks.filter((t) =>
    filter === "todas" ? true : filter === "pendientes" ? !t.done : t.done
  );

  return (
    <div className="mx-auto max-w-xl p-6">
      <h1 className="mb-4 text-2xl font-bold">Tareas</h1>

      <div className="mb-4 flex gap-2">
        <input
          className="flex-1 rounded border border-gray-300 px-3 py-2"
          placeholder="Tarea"
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") addTask();
          }}
        />
        <button
          className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
          onClick={addTask}
        >
          Agregar
        </button>
      </div>

      <div className="mb-4">
        <select
          className="rounded border border-gray-300 px-3 py-2"
          value={filter}
          onChange={(e) => setFilter(e.target.value as Filter)}
        >
          <option value="todas">Todas</option>
          <option value="pendientes">Pendientes</option>
          <option value="hechas">Hechas</option>
        </select>
      </div>

      <ul className="space-y-2">
        {visible.map((task) => (
          <li
            key={task.id}
            className="flex items-center gap-2 rounded border border-gray-200 p-3"
          >
            {editingId === task.id ? (
              <>
                <input
                  className="flex-1 rounded border border-gray-300 px-3 py-1"
                  placeholder="Nuevo título"
                  value={editText}
                  onChange={(e) => setEditText(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") saveTitle(task.id);
                  }}
                />
                <button
                  className="rounded bg-green-600 px-3 py-1 text-white hover:bg-green-700"
                  onClick={() => saveTitle(task.id)}
                >
                  Guardar
                </button>
              </>
            ) : (
              <>
                <span className="flex-1">
                  {task.title}
                  {task.done && " (hecha)"}
                </span>
                {!task.done && (
                  <button
                    className="rounded bg-green-600 px-3 py-1 text-white hover:bg-green-700"
                    onClick={() => markDone(task.id)}
                  >
                    Hecha
                  </button>
                )}
                <button
                  className="rounded bg-gray-600 px-3 py-1 text-white hover:bg-gray-700"
                  onClick={() => startEdit(task)}
                >
                  Renombrar
                </button>
              </>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

