                    {task.done ? " (hecha)" : ""}
                  </span>
                  {!task.done && (
                    <button
                      type="button"
                      onClick={() => markDone(task.id)}
                      className="rounded bg-green-600 px-3 py-1 text-white hover:bg-green-700"
                    >
                      Hecha
                    </button>
                  )}
                  <button
                    type="button"
                    onClick={() => {
                      setEditingId(task.id);
                      setEditTitle("");
                    }}
                    className="rounded bg-gray-600 px-3 py-1 text-white hover:bg-gray-700"
                  >
