export type Choice = "perros" | "gatos";

type Store = {
  votes: Record<Choice, number>;
};

const globalForDb = globalThis as unknown as { __pollStore?: Store };

if (!globalForDb.__pollStore) {
  globalForDb.__pollStore = { votes: { perros: 0, gatos: 0 } };
}

const store: Store = globalForDb.__pollStore;

export type Results = {
  perros: { votes: number; percent: number };
  gatos: { votes: number; percent: number };
  total: number;
};

export function getResults(): Results {
  const p = store.votes.perros;
  const g = store.votes.gatos;
  const total = p + g;
  return {
    perros: { votes: p, percent: total === 0 ? 0 : Math.round((p / total) * 100) },
    gatos: { votes: g, percent: total === 0 ? 0 : Math.round((g / total) * 100) },
    total,
  };
}

export function addVote(choice: Choice): void {
  store.votes[choice] += 1;
}

export function resetVotes(): void {
  store.votes.perros = 0;
  store.votes.gatos = 0;
}

