  store.votes.perros = 0;
  store.votes.gatos = 0;
}

export function getResults() {
  const perros = store.votes.perros;
  const gatos = store.votes.gatos;
  const total = perros + gatos;
  const pct = (n: number) => (total === 0 ? 0 : Math.round((n / total) * 100));
  return {
    perros: { votes: perros, percent: pct(perros) },
    gatos: { votes: gatos, percent: pct(gatos) },
    total,
  };
}

