"use client";

import { useEffect, useState } from "react";

type Results = {
  perros: { votes: number; percent: number };
  gatos: { votes: number; percent: number };
  total: number;
};

export default function Poll() {
  const [results, setResults] = useState<Results | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetch("/api/votes", { cache: "no-store" })
      .then((r) => {
        if (!r.ok) throw new Error();
        return r.json();
      })
      .then((data: Results) => {
        if (!cancelled) setResults(data);
      })
      .catch(() => {
        if (!cancelled) setError("No se pudieron cargar los resultados");
      });
    return () => {
      cancelled = true;
    };
  }, []);

  async function send(init: RequestInit) {
    setBusy(true);
    setError(null);
    try {
      const res = await fetch("/api/votes", init);
      if (!res.ok) throw new Error();
      setResults((await res.json()) as Results);
    } catch {
      setError("Ocurrió un error, intentá de nuevo");
    } finally {
      setBusy(false);
    }
  }

  const voteFor = (choice: "perros" | "gatos") =>
    send({
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ choice }),
    });

  const resetVotes = () => send({ method: "DELETE" });

  return (
    <div className="w-full max-w-md rounded-xl bg-white p-6 shadow-md">
      <h1 className="mb-6 text-center text-2xl font-bold text-gray-900">
        ¿Perros o Gatos?
      </h1>

      <div className="mb-6 flex gap-3">
        <button
          onClick={() => voteFor("perros")}
          disabled={busy}
          className="flex-1 rounded-lg bg-amber-500 px-4 py-2 font-semibold text-white hover:bg-amber-600 disabled:opacity-50"
        >
          Votar Perros
        </button>
        <button
          onClick={() => voteFor("gatos")}
          disabled={busy}
          className="flex-1 rounded-lg bg-indigo-500 px-4 py-2 font-semibold text-white hover:bg-indigo-600 disabled:opacity-50"
        >
          Votar Gatos
        </button>
      </div>

      {results ? (
        <div className="space-y-4">
          <div>
            <p className="mb-1 font-medium text-gray-800">
              Perros: {results.perros.percent}% ({results.perros.votes} votos)
            </p>
            <div className="h-3 w-full overflow-hidden rounded-full bg-gray-200">
              <div
                className="h-full bg-amber-500 transition-all"
                style={{ width: `${results.perros.percent}%` }}
              />
            </div>
          </div>
          <div>
            <p className="mb-1 font-medium text-gray-800">
              Gatos: {results.gatos.percent}% ({results.gatos.votes} votos)
            </p>
            <div className="h-3 w-full overflow-hidden rounded-full bg-gray-200">
              <div
                className="h-full bg-indigo-500 transition-all"
                style={{ width: `${results.gatos.percent}%` }}
              />
            </div>
          </div>
        </div>
      ) : (
        <p className="text-center text-gray-500">Cargando...</p>
      )}

      {error && <p className="mt-4 text-center text-red-600">{error}</p>}

      <button
        onClick={resetVotes}
        disabled={busy}
        className="mt-6 w-full rounded-lg border border-gray-300 px-4 py-2 font-medium text-gray-700 hover:bg-gray-100 disabled:opacity-50"
      >
        Reiniciar
      </button>
    </div>
  );
}

