export type Product = {
  id: number;
  name: string;
  number: number;
};

type DB = {
  products: Product[];
  nextId: number;
};

const globalForDb = globalThis as unknown as { __catalogDb?: DB };

export const db: DB =
  globalForDb.__catalogDb ??
  (globalForDb.__catalogDb = { products: [], nextId: 1 });

export const PAGE_SIZE = 5;

export function seedProducts(): { created: boolean; count: number } {
  if (db.products.length > 0) {
    return { created: false, count: db.products.length };
  }
  for (let i = 1; i <= 12; i++) {
    db.products.push({ id: db.nextId++, name: `Producto ${i}`, number: i });
  }
  return { created: true, count: db.products.length };
}

export function queryProducts(search: string, page: number) {
  const q = search.trim().toLowerCase();
  const filtered = db.products
    .filter((p) => p.name.toLowerCase().includes(q))
    .sort((a, b) => a.number - b.number);
  const total = filtered.length;
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const safePage = Math.min(Math.max(1, page), totalPages);
  const items = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);
  return { items, total, page: safePage, totalPages, pageSize: PAGE_SIZE };
}

