import { randomBytes, scryptSync, timingSafeEqual } from "crypto";

export type User = {
  id: string;
  email: string;
  salt: string;
  hash: string;
};

export type Note = {
  id: string;
  userId: string;
  text: string;
  createdAt: number;
};

type DB = {
  users: User[];
  notes: Note[];
  sessions: Map<string, string>; // token -> userId
};

const g = globalThis as unknown as { __notesDb?: DB };

if (!g.__notesDb) {
  g.__notesDb = {
    users: [],
    notes: [],
    sessions: new Map(),
  };
}

export const db: DB = g.__notesDb;

export const SESSION_COOKIE = "session";

export function hashPassword(password: string, salt: string): string {
  return scryptSync(password, salt, 64).toString("hex");
}

export function createUser(email: string, password: string): User {
  const salt = randomBytes(16).toString("hex");
  const user: User = {
    id: randomBytes(8).toString("hex"),
    email,
    salt,
    hash: hashPassword(password, salt),
  };
  db.users.push(user);
  return user;
}

export function findUserByEmail(email: string): User | undefined {
  return db.users.find((u) => u.email === email);
}

export function verifyPassword(user: User, password: string): boolean {
  const candidate = Buffer.from(hashPassword(password, user.salt), "hex");
  const actual = Buffer.from(user.hash, "hex");
  return candidate.length === actual.length && timingSafeEqual(candidate, actual);
}

export function createSession(userId: string): string {
  const token = randomBytes(32).toString("hex");
  db.sessions.set(token, userId);
  return token;
}

export function getUserFromRequest(req: Request): User | null {
  const cookie = req.headers.get("cookie") || "";
  const match = cookie
    .split(";")
    .map((c) => c.trim())
    .find((c) => c.startsWith(SESSION_COOKIE + "="));
  if (!match) return null;
  const token = match.slice(SESSION_COOKIE.length + 1);
  const userId = db.sessions.get(token);
  if (!userId) return null;
  return db.users.find((u) => u.id === userId) || null;
}

export function getToken(req: Request): string | null {
  const cookie = req.headers.get("cookie") || "";
  const match = cookie
    .split(";")
    .map((c) => c.trim())
    .find((c) => c.startsWith(SESSION_COOKIE + "="));
  return match ? match.slice(SESSION_COOKIE.length + 1) : null;
}

