export default function NotesApp() {
  const [loading, setLoading] = useState(true);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [notes, setNotes] = useState<Note[]>([]);
  const [noteText, setNoteText] = useState("");

  const loadNotes = useCallback(async () => {
    const res = await fetch("/api/notes");
    if (res.ok) {
      const data = await res.json();
      setNotes(data.notes);
    }
  }, []);

  useEffect(() => {
    (async () => {
      try {
        const res = await fetch("/api/me");
        if (res.ok) {
          const data = await res.json();
          setUserEmail(data.email);
          await loadNotes();
        }
      } finally {
        setLoading(false);
      }
    })();
  }, [loadNotes]);

  async function auth(kind: "register" | "login") {
    setError("");
    const res = await fetch(`/api/${kind}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      setError(data.error || "Datos incorrectos");
      return;
    }
    setUserEmail(data.email);
    setPassword("");
    await loadNotes();
  }

  async function logout() {
    await fetch("/api/logout", { method: "POST" });
    setUserEmail(null);
    setNotes([]);
    setEmail("");
    setPassword("");
    setError("");
  }

  async function addNote() {
    const text = noteText.trim();
    if (!text) return;
    const res = await fetch("/api/notes", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text }),
    });
    if (res.ok) {
      setNoteText("");
      await loadNotes();
    }
  }

  if (loading) {
    return <p className="p-6 text-gray-500">Cargando...</p>;
  }

  if (!userEmail) {
    return (
      <div className="mx-auto mt-16 flex max-w-sm flex-col gap-3 rounded-lg border border-gray-300 bg-white p-6 shadow-sm">
        <h1 className="text-xl font-semibold text-gray-900">Notas privadas</h1>
        <input
          className="rounded border border-gray-300 px-3 py-2 text-gray-900"
          placeholder="Email"
          type="text"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <input
          className="rounded border border-gray-300 px-3 py-2 text-gray-900"
          placeholder="Contraseña"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <div className="flex gap-2">
          <button
            className="flex-1 rounded bg-blue-600 px-3 py-2 text-white hover:bg-blue-700"
            onClick={() => auth("register")}
          >
            Crear cuenta
          </button>
          <button
            className="flex-1 rounded bg-gray-800 px-3 py-2 text-white hover:bg-gray-900"
            onClick={() => auth("login")}
          >
            Entrar
          </button>
        </div>
        {error && <p className="text-sm text-red-600">{error}</p>}
      </div>
    );
  }

  return (
    <div className="mx-auto mt-16 flex max-w-md flex-col gap-4 rounded-lg border border-gray-300 bg-white p-6 shadow-sm">
      <div className="flex items-center justify-between">
        <p className="font-medium text-gray-900">Hola, {userEmail}</p>
        <button
          className="rounded bg-gray-200 px-3 py-1 text-gray-900 hover:bg-gray-300"
          onClick={logout}
        >
          Salir
        </button>
      </div>
      <div className="flex gap-2">
        <input
          className="flex-1 rounded border border-gray-300 px-3 py-2 text-gray-900"
          placeholder="Nota"
          value={noteText}
          onChange={(e) => setNoteText(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") addNote();
          }}
        />
        <button
          className="rounded bg-blue-600 px-3 py-2 text-white hover:bg-blue-700"
          onClick={addNote}
        >
          Agregar
        </button>
      </div>
      <ul className="flex flex-col gap-2">
        {notes.map((n) => (
          <li
            key={n.id}
            className="rounded border border-gray-200 bg-gray-50 px-3 py-2 text-gray-900"
          >
            {n.text}
          </li>
        ))}
      </ul>
    </div>
  );
}

