"use client";

import { useState } from "react";
import { SEED, type Item } from "@/lib/data";
import EmployeesForm from "@/components/EmployeesForm";
import EmployeesList from "@/components/EmployeesList";

export default function EmployeesPage() {
  const [items, setItems] = useState<Item[]>(SEED.map((i) => ({ ...i })));

  function add(name: string, amount: number) {
    setItems([...items, { id: Date.now(), name, amount, active: true }]);
  }

  function toggle(id: number) {
    setItems((prev) =>
      prev.map((i) => (i.id === id ? { ...i, active: !i.active } : i))
    );
  }

  return (
    <div className="flex flex-col gap-2">
      <h2 className="text-xl font-bold">Empleados</h2>
      <EmployeesForm onAdd={add} />
      <EmployeesList items={items} onToggle={toggle} />
    </div>
  );
}

files.components/EmployeesRow.tsx:
import type { Item } from "@/lib/data";

export default function EmployeesRow({
  item,
  onToggle,
}: {
  item: Item;
  onToggle: (id: number) => void;
}) {
  return (
    <div className="flex items-center gap-2">
      <span className="font-semibold">{item.name}</span>
      {!item.active && <span className="text-gray-500">(inactivo)</span>}
      <span>Sueldo: {item.amount}</span>
      <button
        type="button"
        className="rounded border px-2 py-0.5 text-sm"
        onClick={() => onToggle(item.id)}
      >
        Alternar
      </button>
    </div>
  );
}

